pub fn decodeEvent(reader: *std.Io.Reader) DecodeError!global_events.Event {
    const code = (try reader.peek(1))[0] & 0x7f;
    return switch (code) {
        0 => .{ .InputDeviceValuator = try DeviceValuatorEvent.decode(reader) },
        1 => .{ .InputDeviceKeyPress = try DeviceKeyPressEvent.decode(reader) },
        2 => .{ .InputDeviceKeyRelease = try DeviceKeyPressEvent.decode(reader) },
        3 => .{ .InputDeviceButtonPress = try DeviceKeyPressEvent.decode(reader) },
        4 => .{ .InputDeviceButtonRelease = try DeviceKeyPressEvent.decode(reader) },
        5 => .{ .InputDeviceMotionNotify = try DeviceKeyPressEvent.decode(reader) },
        6 => .{ .InputDeviceFocusIn = try DeviceFocusInEvent.decode(reader) },
        7 => .{ .InputDeviceFocusOut = try DeviceFocusInEvent.decode(reader) },
        8 => .{ .InputProximityIn = try DeviceKeyPressEvent.decode(reader) },
        9 => .{ .InputProximityOut = try DeviceKeyPressEvent.decode(reader) },
        10 => .{ .InputDeviceStateNotify = try DeviceStateNotifyEvent.decode(reader) },
        11 => .{ .InputDeviceMappingNotify = try DeviceMappingNotifyEvent.decode(reader) },
        12 => .{ .InputChangeDeviceNotify = try ChangeDeviceNotifyEvent.decode(reader) },
        13 => .{ .InputDeviceKeyStateNotify = try DeviceKeyStateNotifyEvent.decode(reader) },
        14 => .{ .InputDeviceButtonStateNotify = try DeviceButtonStateNotifyEvent.decode(reader) },
        15 => .{ .InputDevicePresenceNotify = try DevicePresenceNotifyEvent.decode(reader) },
        16 => .{ .InputDevicePropertyNotify = try DevicePropertyNotifyEvent.decode(reader) },
        else => blk: {
            const packet = try reader.take(32);
            var raw: [32]u8 = undefined;
            @memcpy(raw[0..], packet);
            break :blk .{ .Unknown = .{
                .code = packet[0] & 0x7f,
                .sequence = std.mem.readInt(u16, packet[2..4], .native),
                .raw = raw,
            } };
        },
    };
}

pub fn decodeXgeEvent(reader: *std.Io.Reader) DecodeError!global_events.Event {
    const header = try reader.peek(10);
    const event_type = std.mem.readInt(u16, header[8..10], .native);
    return switch (event_type) {
        1 => .{ .InputDeviceChanged = try DeviceChangedEvent.decode(reader) },
        2 => .{ .InputKeyPress = try KeyPressEvent.decode(reader) },
        3 => .{ .InputKeyRelease = try KeyPressEvent.decode(reader) },
        4 => .{ .InputButtonPress = try ButtonPressEvent.decode(reader) },
        5 => .{ .InputButtonRelease = try ButtonPressEvent.decode(reader) },
        6 => .{ .InputMotion = try ButtonPressEvent.decode(reader) },
        7 => .{ .InputEnter = try EnterEvent.decode(reader) },
        8 => .{ .InputLeave = try EnterEvent.decode(reader) },
        9 => .{ .InputFocusIn = try EnterEvent.decode(reader) },
        10 => .{ .InputFocusOut = try EnterEvent.decode(reader) },
        11 => .{ .InputHierarchy = try HierarchyEvent.decode(reader) },
        12 => .{ .InputProperty = try PropertyEvent.decode(reader) },
        13 => .{ .InputRawKeyPress = try RawKeyPressEvent.decode(reader) },
        14 => .{ .InputRawKeyRelease = try RawKeyPressEvent.decode(reader) },
        15 => .{ .InputRawButtonPress = try RawButtonPressEvent.decode(reader) },
